javascript:
/* ==========================================================================
   LIFE · CLIENT - 360 · v8.1  (full script — lookup fix)
   Paste into: Web Page › Scripting › Javascript
   Works in both a Frappe Web Page and a Custom HTML Block (root_element).
   ========================================================================== */
(function () {
"use strict";

const ROOT = (typeof root_element !== "undefined" && root_element) ? root_element : document;
const APP = ROOT.querySelector ? ROOT.querySelector("#c360App") : null;
if (!APP || APP.dataset.c360Ready === "1") return;
APP.dataset.c360Ready = "1";

const $ = (s, el) => (el || APP).querySelector(s);
const $$ = (s, el) => Array.from((el || APP).querySelectorAll(s));

/* --------------------------------------------------------------------------
   CONFIG — business rules live here (edit values, not code)
   -------------------------------------------------------------------------- */
const CFG = {
  EXCLUDED_BRANCHES: ["Testing Branch", "Head Office"],
  PAGE_SIZE: 10,
  PRINT_FORMAT: "Consultaion Patient Sales Invoice",

  /* Client tier by lifetime paid amount (highest first) */
  TIERS: [
    { key: "VVIP", min: 500000, icon: "👑", tone: "purple" },
    { key: "VIP",  min: 200000, icon: "💎", tone: "blue" },
    { key: "HNI",  min: 100000, icon: "⭐", tone: "amber" }
  ],

  ACTIVE_DAYS: 30,               /* last session within → Active      */
  IRREGULAR_DAYS: 90,            /* within → Irregular, beyond → Stopped */
  DEFAULT_SESSION_GAP_DAYS: 7,   /* used when a plan has no due date  */
  BEHIND_RATIO: 0.75,            /* done < 75% of expected → Behind   */
  REGULAR_RATIO: 0.75,           /* monthly visits ≥ 75% of plan pace → Regular */

  LINKS: {
    billing: "/life-home?view=billing",
    appt: "/life-home?view=appt",
    service: "/life-home?view=service",
    followup: "/life-home?view=followup",
    documents: "/life-home?view=documents",
    stock: "/life-home?view=stock",
    conversions: "/life-home?view=conversions"
  },

  CONVERSION_DOCTYPE: "LIFE Client Package Conversion Same Client Package To Package",
  STOCK_API: "client_stock_entries_api_v14",
  CONCERN_DOCTYPES: ["Client Complaint", "Client Concern", "Client Grievance", "LIFE Grievance", "Grievance", "Customer Complaint"],
  DIET_DOCTYPES: ["Client Diet Plan", "Diet Plan", "Diet Chart", "LIFE Diet Plan", "Client Diet Chart"],

  MEDICAL_KEYWORDS: ["diabet", "thyroid", "hypertension", "blood pressure", " bp", "cardiac", "heart", "pregnan", "lactat",
    "pcod", "pcos", "asthma", "epilep", "seizure", "keloid", "cancer", "tumour", "tumor", "kidney", "renal", "liver",
    "allerg", "hepatitis", "hiv", "steroid", "anticoag", "blood thinner", "warfarin", "surgery", "implant", "pacemaker", "psoria", "vitiligo"],

  PREF_KEY: "c360.v8."
};

/* --------------------------------------------------------------------------
   WEBSITE SHELL — hide public navbar / footer on this page only
   -------------------------------------------------------------------------- */
function hideShell() {
  if (!document.body) return;
  document.body.classList.add("c360-page");
  const sel = "body > header, body > nav, header.navbar, nav.navbar, .web-header, .website-header, .page-header, .page-breadcrumbs, body > footer, footer, .web-footer, .website-footer, .page-footer, .footer-subscribe, .newsletter-section";
  document.querySelectorAll(sel).forEach(el => {
    if (APP.contains(el)) return;
    el.style.setProperty("display", "none", "important");
    el.setAttribute("aria-hidden", "true");
  });
}
hideShell();
setTimeout(hideShell, 400);
setTimeout(hideShell, 1500);

/* --------------------------------------------------------------------------
   HELPERS
   -------------------------------------------------------------------------- */
const esc = v => String(v == null ? "" : v).replace(/[&<>"']/g, c => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c]));
const num = v => { const n = parseFloat(v); return Number.isFinite(n) ? n : 0; };
const r0 = v => (Math.abs(v) < 1 ? 0 : v);
const pad = n => String(n).padStart(2, "0");
const iso = d => d.getFullYear() + "-" + pad(d.getMonth() + 1) + "-" + pad(d.getDate());
const TODAY = () => iso(new Date());
const d10 = v => String(v || "").slice(0, 10);
const MON = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];

function money(v, dec) {
  const n = r0(num(v));
  return "₹" + n.toLocaleString("en-IN", { maximumFractionDigits: dec == null ? 0 : dec });
}
function parseD(s) {
  s = d10(s);
  if (!/^\d{4}-\d{2}-\d{2}$/.test(s)) return null;
  const p = s.split("-").map(Number);
  return new Date(p[0], p[1] - 1, p[2]);
}
function daysBetween(a, b) {
  const A = parseD(a), B = parseD(b);
  if (!A || !B) return null;
  return Math.round((B - A) / 86400000);
}
function addDays(s, n) { const d = parseD(s); if (!d) return ""; d.setDate(d.getDate() + n); return iso(d); }
function fdate(s) { const d = parseD(s); return d ? pad(d.getDate()) + "-" + MON[d.getMonth()] + "-" + String(d.getFullYear()).slice(-2) : "—"; }
function ftime(t) {
  const m = String(t || "").match(/^(\d{1,2}):(\d{2})/);
  if (!m) return "";
  let h = +m[1]; const ap = h >= 12 ? "pm" : "am"; h = h % 12 || 12;
  return h + ":" + m[2] + " " + ap;
}
const isExcluded = b => CFG.EXCLUDED_BRANCHES.includes(String(b || "").trim());
const lc = v => String(v || "").trim().toLowerCase();
const plural = (n, w) => n + " " + w + (n === 1 ? "" : "s");

function cleanMobile(v) {
  let d = String(v || "").replace(/\D/g, "");
  if (d.length === 12 && d.startsWith("91")) d = d.slice(2);
  if (d.length === 11 && d.startsWith("0")) d = d.slice(1);
  return d;
}
function maskMobile(v) {
  const d = cleanMobile(v);
  if (!d) return "";
  if (d.length <= 6) return "••••••";
  return d.slice(0, 3) + "****" + d.slice(-3);
}
function phoneHtml(v, label) {
  const d = cleanMobile(v);
  if (!d) return "";
  return `<span class="c3-phone" tabindex="0" aria-label="${esc(label || "Mobile")}: hover or focus to reveal">` +
    (label ? `<em>${esc(label)}</em>` : "") +
    `<span class="c3-phone-m">📱 ${esc(maskMobile(d))}</span><span class="c3-phone-f">📱 ${esc(d)}</span></span>`;
}
function genderEmoji(sex) {
  const s = lc(sex);
  if (s.startsWith("f")) return { e: "👩", t: "Female" };
  if (s.startsWith("m")) return { e: "👨", t: "Male" };
  return { e: "🧑", t: sex || "Not set" };
}
function initials(name) {
  return String(name || "?").trim().split(/\s+/).map(w => w[0]).join("").slice(0, 2).toUpperCase();
}
function stripHtml(h) {
  const d = document.createElement("div");
  d.innerHTML = String(h || "");
  return (d.textContent || "").trim();
}
function slug(dt) { return String(dt).toLowerCase().replace(/\s+/g, "-"); }
function openDesk(doctype, name) {
  window.open("/app/" + slug(doctype) + "/" + encodeURIComponent(name), "_blank", "noopener");
}
function portalLink(key, pid) {
  const base = CFG.LINKS[key] || "/life-home";
  return base + (base.includes("?") ? "&" : "?") + "patient=" + encodeURIComponent(pid || "");
}
function openBill(inv) {
  if (!inv) return;
  const p = new URLSearchParams({ doctype: "Sales Invoice", name: inv, format: CFG.PRINT_FORMAT, no_letterhead: "0" });
  window.open("/printview?" + p.toString(), "_blank", "noopener");
}
function pref(key, val) {
  try {
    if (val === undefined) return JSON.parse(localStorage.getItem(CFG.PREF_KEY + key) || "null");
    localStorage.setItem(CFG.PREF_KEY + key, JSON.stringify(val));
  } catch (e) { return null; }
}
function toast(msg, tone) {
  let host = $("#c3Toast");
  if (!host) return;
  const t = document.createElement("div");
  t.className = "c3-toast tone-" + (tone || "ok");
  t.textContent = msg;
  host.appendChild(t);
  setTimeout(() => t.remove(), 3200);
}
async function safe(p, fallback) { try { return await p; } catch (e) { void 0; return fallback; } }

/* --------------------------------------------------------------------------
   API
   -------------------------------------------------------------------------- */
function csrf() { return (window.frappe && frappe.csrf_token) || window.csrf_token || ""; }

async function call(method, args, raw) {
  const res = await fetch("/api/method/" + method, {
    method: "POST",
    credentials: "same-origin",
    headers: { "Content-Type": "application/json", "Accept": "application/json", "X-Frappe-CSRF-Token": csrf() },
    body: JSON.stringify(args || {})
  });
  let data = {};
  try { data = await res.json(); } catch (e) { /* non-JSON */ }
  if (!res.ok || data.exc || data.exc_type) {
    let msg = data.exception || "";
    try { if (!msg && data._server_messages) msg = JSON.parse(JSON.parse(data._server_messages)[0]).message; } catch (e) { /* ignore */ }
    const err = new Error(stripHtml(msg) || ("Request failed (" + res.status + ")"));
    err.raw = JSON.stringify(data);
    err.status = res.status;
    throw err;
  }
  return raw ? data : data.message;
}

function badField(e) {
  const t = (e && (e.raw || "")) + " " + (e && e.message || "");
  const m = t.match(/Unknown column '(?:[`\w\s]+\.)?`?(\w+)`?'/i) ||
            t.match(/Field not permitted in query:?\s*`?(\w+)/i) ||
            t.match(/Invalid field:?\s*`?(\w+)/i);
  return m ? m[1] : null;
}

async function pagedList(doctype, filters, fields, limit, order) {
  const PAGE = 500;
  let out = [], start = 0;
  while (out.length < limit) {
    const len = Math.min(PAGE, limit - out.length);
    const rows = await call("frappe.client.get_list", {
      doctype, filters: filters || [], fields, limit_page_length: len, limit_start: start, order_by: order || "creation desc"
    }) || [];
    out = out.concat(rows);
    if (rows.length < len) break;
    start += len;
  }
  return out;
}

async function list(doctype, filters, fields, limit, order) {
  let f = (fields || ["name"]).slice();
  for (let i = 0; i < 12; i++) {
    try { return await pagedList(doctype, filters, f, limit || 500, order); }
    catch (e) {
      const bad = badField(e);
      if (bad && f.includes(bad) && f.length > 1) { f = f.filter(x => x !== bad); continue; }
      if (order && /order|column/i.test(e.message || "")) { order = "creation desc"; continue; }
      throw e;
    }
  }
  return [];
}

async function inChunks(ids, fn, size) {
  const out = [];
  size = size || 100;
  for (let i = 0; i < ids.length; i += size) {
    const rows = await fn(ids.slice(i, i + size));
    if (rows && rows.length) out.push(...rows);
  }
  return out;
}

const getDoc = (doctype, name) => call("frappe.client.get", { doctype, name });

async function pooled(items, size, fn) {
  const out = [];
  for (let i = 0; i < items.length; i += size) {
    const part = await Promise.all(items.slice(i, i + size).map(x => fn(x).catch(() => null)));
    out.push(...part);
  }
  return out;
}

const META = {};
async function metaFields(doctype) {
  if (META[doctype] !== undefined) return META[doctype];
  try {
    const data = await call("frappe.desk.form.load.getdoctype", { doctype }, true);
    const d = (data.docs || []).find(x => x.name === doctype);
    META[doctype] = d ? (d.fields || []) : null;
  } catch (e) { META[doctype] = null; }
  return META[doctype];
}

/* --------------------------------------------------------------------------
   SHARED BUSINESS LOGIC
   -------------------------------------------------------------------------- */
const STATUS = {
  active:      { e: "✅", l: "Active",      c: "ok" },
  irregular:   { e: "⚠️", l: "Irregular",   c: "warn" },
  stopped:     { e: "🚫", l: "Stopped",     c: "neg" },
  completed:   { e: "🏁", l: "Completed",   c: "info" },
  not_started: { e: "🆕", l: "Not started", c: "mute" }
};
const statusBadge = s => { const x = STATUS[s] || STATUS.not_started; return `<span class="c3-pill tone-${x.c}">${x.e} ${x.l}</span>`; };

function clientStatus(lastSession, plans) {
  let s = "not_started";
  if (lastSession) {
    const g = daysBetween(lastSession, TODAY());
    s = g <= CFG.ACTIVE_DAYS ? "active" : g <= CFG.IRREGULAR_DAYS ? "irregular" : "stopped";
  }
  const ps = plans || [];
  if (ps.length && ps.every(p => ["completed", "cancelled"].includes(lc(p.status))) && ps.some(p => lc(p.status) === "completed")) s = "completed";
  return s;
}

function planHealth(p) {
  const st = lc(p.status);
  const total = num(p.total);
  const done = total > 0 ? Math.min(num(p.done), total) : num(p.done);
  const r = { total, done, balance: Math.max(0, total - done), pct: total > 0 ? Math.round(done / total * 100) : 0,
    state: "ok", overdueDays: 0, expected: 0, due: d10(p.due), estimated: false };
  if (st === "cancelled") { r.state = "cancelled"; return r; }
  if ((total > 0 && done >= total) || st === "completed") { r.state = "done"; if (!total) r.pct = 100; return r; }
  const start = d10(p.start);
  if (!start || !total) { r.state = "unknown"; return r; }
  if (!r.due) { r.due = addDays(start, total * CFG.DEFAULT_SESSION_GAP_DAYS); r.estimated = true; }
  const t = TODAY();
  const span = Math.max(1, daysBetween(start, r.due));
  const elapsed = Math.max(0, daysBetween(start, t));
  r.expected = Math.min(total, Math.round(total * Math.min(1, elapsed / span) * 10) / 10);
  if (t > r.due) { r.state = "overdue"; r.overdueDays = daysBetween(r.due, t); return r; }
  if (r.expected >= 1 && done < r.expected * CFG.BEHIND_RATIO && r.expected - done >= 1) r.state = "behind";
  return r;
}
const PLAN_STATE = {
  ok:        { e: "▲", l: "On track",  c: "ok" },
  behind:    { e: "▼", l: "Behind",    c: "warn" },
  overdue:   { e: "⛔", l: "Overdue",   c: "neg" },
  done:      { e: "🏁", l: "Completed", c: "info" },
  cancelled: { e: "✕", l: "Cancelled", c: "mute" },
  unknown:   { e: "•", l: "No schedule", c: "mute" }
};
function planStateChip(h) {
  const x = PLAN_STATE[h.state] || PLAN_STATE.unknown;
  const extra = h.state === "overdue" ? ` ${h.overdueDays}d` : h.state === "behind" ? ` ${Math.round(h.expected - h.done)} short` : "";
  return `<span class="c3-pill tone-${x.c}">${x.e} ${x.l}${extra}</span>`;
}

function dueInfo(invoices) {
  const t = TODAY();
  const r = { pending: 0, withDues: 0, overdue: 0, overdueAmt: 0, next: null, nextAmt: 0, oldestOverdue: null };
  (invoices || []).forEach(i => {
    const o = r0(num(i.outstanding_amount));
    if (o <= 0) return;
    r.pending += o; r.withDues++;
    const dd = d10(i.due_date);
    if (dd && dd < t) { r.overdue++; r.overdueAmt += o; if (!r.oldestOverdue || dd < r.oldestOverdue) r.oldestOverdue = dd; }
    else if (dd && (!r.next || dd < r.next)) { r.next = dd; r.nextAmt = o; }
  });
  return r;
}

function tierFor(paid) {
  for (const t of CFG.TIERS) if (paid >= t.min) return t;
  return null;
}
const tierBadge = t => t ? `<span class="c3-pill tone-${t.tone} c3-tier">${t.icon} ${t.key}</span>` : "";

/* --------------------------------------------------------------------------
   MAIN LIST PAGE
   -------------------------------------------------------------------------- */
const S = {
  all: [], filtered: [], page: 1, from: null, to: null, unpaid: false,
  collections: [], modes: [], invCache: {}, seq: 0, totals: { inv: 0, paid: 0, pending: 0 }, collected: 0
};

function billingMonth(offset) {
  const n = new Date();
  let y = n.getFullYear(), m = n.getMonth();
  if (n.getDate() < 6) m -= 1;
  m -= (offset || 0);
  const from = new Date(y, m, 6), to = new Date(y, m + 1, 5);
  return [iso(from), iso(to)];
}
function qRange(key) {
  const n = new Date();
  if (key === "all") return [null, null];
  if (key === "today") { const t = iso(n); return [t, t]; }
  if (key === "yesterday") { n.setDate(n.getDate() - 1); const t = iso(n); return [t, t]; }
  if (key === "thismonth") return billingMonth(0);
  if (key === "lastmonth") return billingMonth(1);
  return [null, null];
}

const setStatus = h => { const el = $("#c3StatusBar"); if (el) el.innerHTML = h; };
const selMode = () => String(($("#c3Mode") || {}).value || "").trim();

function renderLoading() {
  $("#c3Body").innerHTML = `<tr><td colspan="12" class="c3-state"><div class="c3-loader"><span>LIFE</span></div><p>Loading clients…</p></td></tr>`;
  $("#c3Pager").hidden = true;
}
function renderEmpty(msg) {
  $("#c3Body").innerHTML = `<tr><td colspan="12" class="c3-state"><div class="c3-state-ic">🔍</div><p>${esc(msg || "No clients match these filters.")}</p><small>Widen the date range or clear filters.</small></td></tr>`;
  $("#c3Pager").hidden = true;
}

async function loadCollections(from, to) {
  const f = [["docstatus", "=", 1], ["payment_type", "=", "Receive"]];
  if (from) f.push(["posting_date", ">=", from]);
  if (to) f.push(["posting_date", "<=", to]);
  const rows = await safe(list("Payment Entry", f,
    ["name", "posting_date", "mode_of_payment", "party", "party_name", "branch", "base_received_amount", "received_amount", "paid_amount"], 50000), []);
  return rows.filter(r => !isExcluded(r.branch));
}
const peAmount = e => num(e.base_received_amount) || num(e.received_amount) || num(e.paid_amount);

async function loadModes() {
  const rows = await safe(list("Mode of Payment", [], ["name", "enabled"], 500, "name asc"), []);
  S.modes = rows.filter(r => r.enabled === undefined || r.enabled === null || Number(r.enabled) !== 0).map(r => r.name);
  fillModes();
}
function fillModes() {
  const sel = $("#c3Mode"); if (!sel) return;
  const prev = sel.value;
  let modes = S.modes.length ? S.modes : [...new Set(S.collections.map(c => c.mode_of_payment).filter(Boolean))];
  modes = [...new Set(modes)].sort((a, b) => a.localeCompare(b));
  sel.innerHTML = `<option value="">All payment modes</option>` + modes.map(m => `<option value="${esc(m)}">${esc(m)}</option>`).join("");
  if (prev && modes.includes(prev)) sel.value = prev;
}

async function loadMain(from, to) {
  const seq = ++S.seq;
  S.from = from; S.to = to; S.unpaid = false;
  $("#c3UnpaidBtn").classList.remove("is-on");
  setStatus("⏳ Loading clients…");
  renderLoading();
  try {
    const f = [];
    if (from) f.push(["start_date", ">=", from]);
    if (to) f.push(["start_date", "<=", to]);
    const raw = await list("Therapy Plan", f,
      ["name", "patient", "patient_name", "start_date", "due_date", "branch", "custom_health_status", "status", "total_sessions", "total_sessions_completed"],
      20000, "start_date desc");
    if (seq !== S.seq) return;

    const plans = raw.filter(p => p.patient && !isExcluded(p.branch));
    const pm = {};
    plans.forEach(p => (pm[p.patient] = pm[p.patient] || []).push(p));
    const ids = Object.keys(pm);

    const [inv, ses, cols, pts] = await Promise.all([
      inChunks(ids, c => list("Sales Invoice", [["patient", "in", c], ["docstatus", "=", 1]],
        ["name", "patient", "posting_date", "due_date", "base_grand_total", "outstanding_amount", "status", "is_return", "branch"], 10000)),
      inChunks(ids, c => list("Therapy Session", [["patient", "in", c], ["docstatus", "!=", 2]],
        ["patient", "start_date", "creation", "branch"], 20000)),
      loadCollections(from, to),
      inChunks(ids, c => list("Patient", [["name", "in", c]], ["name", "patient_name", "customer", "mobile", "sex"], 1000))
    ]);
    if (seq !== S.seq) return;

    S.collections = cols;
    fillModes();

    const P = {}; pts.forEach(p => { P[p.name] = p; });
    const I = {}; S.invCache = {};
    inv.filter(i => !isExcluded(i.branch)).forEach(i => (I[i.patient] = I[i.patient] || []).push(i));
    const SS = {};
    ses.filter(s => !isExcluded(s.branch)).forEach(s => {
      const x = SS[s.patient] = SS[s.patient] || { n: 0, last: null };
      x.n++;
      const d = d10(s.start_date || s.creation);
      if (d && (!x.last || d > x.last)) x.last = d;
    });

    let tInv = 0, tPaid = 0, tPend = 0;
    const rows = ids.map(pid => {
      const ps = pm[pid];
      const first = ps.reduce((a, b) => (!a.start_date ? b : (b.start_date && b.start_date < a.start_date ? b : a)));
      const invs = (I[pid] || []).sort((a, b) => String(b.posting_date).localeCompare(String(a.posting_date)));
      S.invCache[pid] = invs;
      let paidAll = 0, paidRange = 0;
      invs.forEach(i => {
        const paid = num(i.base_grand_total) - num(i.outstanding_amount);
        paidAll += paid;
        const d = d10(i.posting_date);
        if ((!from || d >= from) && (!to || d <= to)) paidRange += paid;
      });
      const due = dueInfo(invs);
      const sx = SS[pid] || { n: 0, last: null };
      const states = ps.map(p => planHealth({ start: p.start_date, due: p.due_date, total: p.total_sessions, done: p.total_sessions_completed, status: p.status }).state);
      const growth = states.includes("overdue") ? { c: "neg", l: "⛔ Overdue plan" }
        : states.includes("behind") ? { c: "warn", l: "▼ Behind" }
        : states.includes("ok") ? { c: "ok", l: "▲ On track" }
        : states.includes("done") ? { c: "info", l: "🏁 Done" } : { c: "mute", l: "—" };
      const pt = P[pid] || {};
      const invCount = invs.filter(i => !Number(i.is_return)).length;
      const paid = r0(from || to ? paidRange : paidAll);
      tInv += invCount; tPaid += paid; tPend += due.pending;
      return {
        id: pid,
        name: first.patient_name || pt.patient_name || pid,
        customer: pt.customer || "",
        mobile: cleanMobile(pt.mobile),
        sex: pt.sex || "",
        joined: first.start_date,
        last: sx.last,
        visits: sx.n,
        paid,
        pending: r0(due.pending),
        withDues: due.withDues,
        overdue: due.overdue,
        invCount,
        medical: ps.some(p => lc(p.custom_health_status) === "medical") ? "Medical" : "Non-Medical",
        branches: [...new Set(ps.map(p => p.branch).filter(b => b && !isExcluded(b)))],
        status: clientStatus(sx.last, ps),
        growth
      };
    });

    rows.sort((a, b) => (b.overdue - a.overdue) || (b.pending - a.pending) || String(a.name).localeCompare(String(b.name)));
    S.all = rows;
    S.totals = { inv: tInv, paid: tPaid, pending: tPend };

    const bsel = $("#c3Branch");
    const prev = bsel.value;
    const branches = [...new Set(rows.flatMap(r => r.branches))].sort();
    bsel.innerHTML = `<option value="">All branches</option>` + branches.map(b => `<option value="${esc(b)}"${b === prev ? " selected" : ""}>${esc(b)}</option>`).join("");

    applyFilters();
    clearTimeout(S.dashTimer);
    S.dashTimer = setTimeout(() => { if (!$("#c3Dash").classList.contains("is-collapsed")) loadDash(); }, 400);
  } catch (e) {
    void 0;
    $("#c3Body").innerHTML = `<tr><td colspan="12" class="c3-state is-error"><div class="c3-state-ic">⚠️</div><p>Client list could not load.</p><small>${esc(e.message)} — press Clear to retry.</small></td></tr>`;
    setStatus("Load failed.");
  }
}

function renderTotals() {
  const branch = $("#c3Branch").value, mode = selMode();
  let cols = S.collections;
  if (branch) cols = cols.filter(c => String(c.branch || "").trim() === branch);
  if (mode) cols = cols.filter(c => String(c.mode_of_payment || "").trim() === mode);
  S.collected = cols.reduce((s, c) => s + peAmount(c), 0);

  const rows = S.filtered;
  const inv = rows.reduce((s, r) => s + r.invCount, 0);
  const paid = rows.reduce((s, r) => s + r.paid, 0);
  const pend = rows.reduce((s, r) => s + r.pending, 0);
  const overdueClients = rows.filter(r => r.overdue > 0).length;

  $("#c3KInv").textContent = inv.toLocaleString("en-IN");
  $("#c3KPaid").textContent = money(paid);
  $("#c3KPaid").title = money(paid, 2);
  $("#c3KCol").textContent = money(S.collected);
  $("#c3KCol").title = (mode ? "Mode: " + mode : "All payment modes") + " · " + money(S.collected, 2);

  const bal = r0(paid - S.collected);
  const bEl = $("#c3KBal"), bLbl = $("#c3KBalHint");
  bEl.textContent = money(Math.abs(bal));
  bEl.className = "c3-kpi-v " + (bal > 0 ? "tone-warn" : bal < 0 ? "tone-info" : "tone-ok");
  bLbl.textContent = bal > 0 ? "▼ Invoice paid not yet collected" : bal < 0 ? "▲ Collected more than invoiced (advances / old dues)" : "✓ Fully matched";

  $("#c3KOut").textContent = money(pend);
  $("#c3KOutHint").textContent = overdueClients ? `⏰ ${plural(overdueClients, "client")} past due date` : "No due dates crossed";
  $("#c3KOutHint").className = "c3-kpi-hint " + (overdueClients ? "tone-neg" : "tone-ok");
}

function modeParties(mode) {
  const key = lc(mode);
  const set = new Set();
  S.collections.forEach(c => {
    if (lc(c.mode_of_payment) !== key) return;
    if (c.party) set.add(lc(c.party));
    if (c.party_name) set.add(lc(c.party_name));
  });
  return set;
}

function applyFilters() {
  const q = lc($("#c3Search").value);
  const branch = $("#c3Branch").value, st = $("#c3Status").value, mode = selMode();
  let rows = S.all.slice();
  if (branch) rows = rows.filter(r => r.branches.includes(branch));
  if (st) rows = rows.filter(r => r.status === st);
  if (mode) { const ps = modeParties(mode); rows = rows.filter(r => ps.has(lc(r.customer)) || ps.has(lc(r.id)) || ps.has(lc(r.name))); }
  if (S.unpaid) rows = rows.filter(r => r.pending > 0).sort((a, b) => (b.overdue - a.overdue) || (b.pending - a.pending));
  const digits = q.replace(/\D/g, "");
  if (q && !(digits.length >= 5 && digits.length === q.length)) rows = rows.filter(r => lc(r.name).includes(q));
  else if (digits.length >= 5) rows = rows.filter(r => r.mobile.includes(digits));
  S.filtered = rows;
  S.page = 1;

  const parts = [];
  if (S.from || S.to) parts.push(`📅 <b>${fdate(S.from) || "any"} → ${fdate(S.to) || "any"}</b>`);
  if (branch) parts.push(`🏢 <b>${esc(branch)}</b>`);
  if (st) parts.push(`${STATUS[st] ? STATUS[st].e : ""} <b>${esc(STATUS[st] ? STATUS[st].l : st)}</b>`);
  if (mode) parts.push(`💳 <b>${esc(mode)}</b>`);
  if (S.unpaid) parts.push(`⚠️ <b>Pending only</b>`);
  setStatus(`Showing <b>${rows.length}</b> of ${S.all.length} clients ${parts.length ? "— " + parts.join(" &nbsp; ") : ""}`);
  $("#c3Count").textContent = rows.length.toLocaleString("en-IN");
  renderTotals();
  renderTable();
}

function renderTable() {
  const rows = S.filtered, total = rows.length;
  if (!total) { renderEmpty(S.all.length ? "No clients match these filters." : "No clients started a plan in this date range."); return; }
  const pages = Math.ceil(total / CFG.PAGE_SIZE);
  S.page = Math.min(Math.max(1, S.page), pages);
  const start = (S.page - 1) * CFG.PAGE_SIZE;
  const view = rows.slice(start, start + CFG.PAGE_SIZE);

  $("#c3Body").innerHTML = view.map((r, i) => {
    const g = genderEmoji(r.sex);
    const med = r.medical === "Medical";
    return `<tr class="c3-row${r.overdue ? " is-overdue" : r.pending > 0 ? " is-due" : ""}" data-pid="${esc(r.id)}" tabindex="0">
      <td class="c3-num-cell">${start + i + 1}</td>
      <td><div class="c3-client-cell"><span class="c3-g" title="${esc(g.t)}">${g.e}</span><div>
        <button type="button" class="c3-client-name" data-open="${esc(r.id)}">${esc(r.name)}</button>
        <div>${phoneHtml(r.mobile)}</div></div></div></td>
      <td>${statusBadge(r.status)}</td>
      <td><span class="c3-pill tone-${r.growth.c}">${r.growth.l}</span></td>
      <td>${fdate(r.joined)}</td>
      <td>${r.last ? fdate(r.last) : "—"}</td>
      <td class="t-c"><span class="c3-count">${r.visits}</span></td>
      <td class="t-r c3-money tone-ok">${money(r.paid)}</td>
      <td class="t-r"><div class="c3-money ${r.pending > 0 ? "tone-neg" : "tone-mute"}">${money(r.pending)}</div>
        ${r.overdue ? `<div class="c3-mini tone-neg">⏰ ${r.overdue} overdue</div>` : r.withDues > 1 ? `<div class="c3-mini tone-warn">🧾 ${r.withDues} with dues</div>` : ""}</td>
      <td><span class="c3-pill tone-${med ? "neg" : "ok"}">${med ? "🩺 Medical" : "🌿 Non-medical"}</span></td>
      <td>${r.branches.map(b => `<span class="c3-chip">${esc(b)}</span>`).join(" ") || "—"}</td>
      <td class="t-c c3-sticky"><button type="button" class="c3-inv-btn${r.pending > 0 ? " has-due" : ""}" data-drawer="${esc(r.id)}">🧾 <b>${r.invCount}</b></button></td>
    </tr>`;
  }).join("");

  const pager = $("#c3Pager");
  pager.hidden = pages <= 1;
  if (pages > 1) {
    $("#c3PageInfo").textContent = `${start + 1}–${Math.min(start + CFG.PAGE_SIZE, total)} of ${total}`;
    $("#c3Prev").disabled = S.page === 1;
    $("#c3Next").disabled = S.page === pages;
    $("#c3PageNums").innerHTML = pageRange(S.page, pages).map(n => n === "…" ? `<span class="c3-dots">…</span>`
      : `<button type="button" class="c3-pg${n === S.page ? " is-on" : ""}" data-page="${n}">${n}</button>`).join("");
  }
}
function pageRange(cur, total) {
  if (total <= 7) return Array.from({ length: total }, (_, i) => i + 1);
  const out = [1];
  const s = Math.max(2, cur - 2), e = Math.min(total - 1, cur + 2);
  if (s > 2) out.push("…");
  for (let i = s; i <= e; i++) out.push(i);
  if (e < total - 1) out.push("…");
  out.push(total);
  return out;
}

function exportCsv() {
  if (!S.filtered.length) { toast("Nothing to export for these filters.", "warn"); return; }
  const head = ["#", "Client", "Mobile (masked)", "Status", "Growth", "Joined", "Last session", "Visits", "Paid", "Pending", "Overdue invoices", "Medical", "Branches"];
  const q = v => `"${String(v == null ? "" : v).replace(/"/g, '""')}"`;
  const lines = S.filtered.map((r, i) => [i + 1, q(r.name), maskMobile(r.mobile), r.status, q(r.growth.l.replace(/^[^\w]+/, "")), r.joined || "", r.last || "", r.visits, Math.round(r.paid), Math.round(r.pending), r.overdue, r.medical, q(r.branches.join(", "))].join(","));
  const blob = new Blob(["\uFEFF" + [head.join(","), ...lines].join("\n")], { type: "text/csv" });
  const a = document.createElement("a");
  a.href = URL.createObjectURL(blob);
  a.download = "client_360_" + TODAY() + ".csv";
  a.click();
  setTimeout(() => URL.revokeObjectURL(a.href), 1000);
}

