function invClass(i) {
  const g = num(i.base_grand_total), o = r0(num(i.outstanding_amount));
  if (o <= 0) return "paid";
  if (d10(i.due_date) && d10(i.due_date) < TODAY()) return "overdue";
  return Math.abs(o - g) < 1 ? "unpaid" : "partial";
}
const INV_STATE = { paid: ["ok", "✅ Paid"], partial: ["warn", "◐ Partial"], unpaid: ["warn", "○ Unpaid"], overdue: ["neg", "⏰ Overdue"] };
function invoiceCard(i) {
  const g = num(i.base_grand_total), o = r0(num(i.outstanding_amount)), c = invClass(i), s = INV_STATE[c];
