      <div><small>Branch</small><span>${esc(i.branch || "—")}</span></div>
    </div></button>`;
}
function renderDrawer() {
  const invs = S.invCache[drawerPid] || [];
  const d = dueInfo(invs);
  const paid = invs.reduce((s, i) => s + num(i.base_grand_total) - num(i.outstanding_amount), 0);
  $("#c3DrawerSum").innerHTML = `
    <div><small>Invoices</small><b>${invs.length}</b></div>
    <div><small>Paid</small><b class="tone-ok">${money(paid)}</b></div>
    <div><small>Balance</small><b class="tone-neg">${money(d.pending)}</b></div>
    <div><small>Overdue</small><b class="${d.overdue ? "tone-neg" : "tone-ok"}">${d.overdue}</b></div>`;
  const list_ = invs.filter(i => drawerFilter === "all" || invClass(i) === drawerFilter || (drawerFilter === "unpaid" && ["unpaid", "overdue"].includes(invClass(i))));
  $("#c3DrawerList").innerHTML = list_.length ? list_.map(invoiceCard).join("") : `<div class="c3-empty-sm">No invoices for this filter.</div>`;
}
