   GLOBAL CLIENT LOOKUP  (fixed)
   -------------------------------------------------------------------------- */
let lookSeq = 0, lookTimer = null, lookRows = [];

function lookupRule(v) {
  const t = String(v || "").trim();
  const d = t.replace(/\D/g, "");
  const nonDigit = t.replace(/[\s+\-()]/g, "");
  if (d && d.length === nonDigit.length) return { ok: d.length >= 5, type: "mobile", q: d };
  return { ok: t.length >= 3, type: "name", q: t };
}

function hideLookup() {
  const el = $("#c3Lookup");
  if (el) el.hidden = true;
  const s = $("#c3Search");
  if (s) s.setAttribute("aria-expanded", "false");
}

const LOOK_FIELDS_FULL = ["name", "patient_name", "mobile", "sex", "branch_name"];
const LOOK_FIELDS_MIN  = ["name", "patient_name", "mobile", "sex"];

async function lookPatients(filters) {
  let rows = await safe(list("Patient", filters, LOOK_FIELDS_FULL, 30, "modified desc"), null);
  if (rows === null) rows = await safe(list("Patient", filters, LOOK_FIELDS_MIN, 30, "modified desc"), []);
  return rows || [];
}

async function runLookup(v) {
  const rule = lookupRule(v);
  if (!rule.ok) { hideLookup(); return; }

  const seq = ++lookSeq;
  const el = $("#c3Lookup");
  if (!el) return;
  el.hidden = false;
  el.innerHTML = `<div class="c3-look-state"><span class="c3-spin"></span> Searching all clients…</div>`;

  const found = [];
  if (rule.type === "mobile") {
    for (const shape of [rule.q, "91" + rule.q, "0" + rule.q]) {
      found.push(...await lookPatients([["mobile", "like", "%" + shape + "%"]]));
      if (found.length >= 30) break;
    }
    if (!found.length) found.push(...await lookPatients([["patient_name", "like", "%" + rule.q + "%"]]));
  } else {
    found.push(...await lookPatients([["patient_name", "like", "%" + rule.q + "%"]]));
    found.push(...await lookPatients([["name", "like", "%" + rule.q + "%"]]));
  }
  if (seq !== lookSeq) return;

  const seen = new Set();
  lookRows = found.filter(p => {
    if (!p || !p.name || seen.has(p.name)) return false;
    if (isExcluded(p.branch_name)) return false;
    if (rule.type === "mobile" && !cleanMobile(p.mobile).includes(rule.q)) return false;
    seen.add(p.name);
    return true;
  }).slice(0, 15);

  $("#c3Search").setAttribute("aria-expanded", "true");

  if (!lookRows.length) {
    el.innerHTML = `<div class="c3-look-state">No client found for “${esc(rule.q)}”.<br>
      <small>Try another spelling, or the first 5 digits of the mobile number.</small></div>`;
    return;
  }

  el.innerHTML = `<div class="c3-look-h">${lookRows.length} matching client${lookRows.length === 1 ? "" : "s"}</div>` +
    lookRows.map((p, i) => {
      const g = genderEmoji(p.sex);
      return `<div class="c3-look-item">
        <span class="c3-g">${g.e}</span>
        <div class="c3-look-main">
          <b>${esc(p.patient_name || p.name)}</b>
          <div class="c3-look-meta">${phoneHtml(p.mobile)}${p.branch_name ? `<span class="c3-chip">🏢 ${esc(p.branch_name)}</span>` : ""}</div>
        </div>
        <div class="c3-look-act">
          <button type="button" class="c3-btn c3-btn-primary c3-btn-sm" data-look-open="${i}">Open 360</button>
          <button type="button" class="c3-btn c3-btn-sm" data-look-row="${i}">Show in list</button>
        </div>
      </div>`;
    }).join("");
}

