/* ---------------- network dashboard ---------------- */
async function loadDash() {
  const set = (id, v) => { const el = $("#" + id); if (el) el.innerHTML = v; };
  $("#c3DashUpdated").textContent = "Updating…";
  try {
    const t = TODAY();
    const d90 = addDays(t, -CFG.IRREGULAR_DAYS), d30 = addDays(t, -CFG.ACTIVE_DAYS);
    const now = new Date();
    const fyFrom = (now.getMonth() >= 3 ? now.getFullYear() : now.getFullYear() - 1) + "-04-01";
    const dFrom = S.from || billingMonth(0)[0];
    let dTo = S.to || t; if (dTo > t) dTo = t;
    const fetchFrom = [fyFrom, dFrom, d90].sort()[0];

    const [plansRaw, sesRaw] = await Promise.all([
      list("Therapy Plan", [], ["patient", "status", "branch"], 60000),
      list("Therapy Session", [["start_date", ">=", fetchFrom], ["start_date", "<=", t], ["docstatus", "!=", 2]], ["patient", "start_date", "branch"], 80000)
    ]);
    const plans = plansRaw.filter(p => p.patient && !isExcluded(p.branch));
    const ses = sesRaw.filter(s => !isExcluded(s.branch));
    const patients = [...new Set(plans.map(p => p.patient))];

    const last = {};
    ses.forEach(s => { const d = d10(s.start_date); if (d >= d90 && (!last[s.patient] || d > last[s.patient])) last[s.patient] = d; });
    let active = 0, irregular = 0, inactive = 0;
    patients.forEach(p => { const l = last[p]; if (!l) inactive++; else if (l >= d30) active++; else irregular++; });

    const completed = new Set(plans.filter(p => lc(p.status) === "completed").map(p => p.patient)).size;
    const bm = {};
    plans.forEach(p => { if (p.branch) (bm[p.branch] = bm[p.branch] || new Set()).add(p.patient); });
    const bNames = Object.keys(bm);
    const top = bNames.sort((a, b) => bm[b].size - bm[a].size)[0] || "—";
    const inServ = {};
    plans.filter(p => !["completed", "cancelled"].includes(lc(p.status))).forEach(p => { if (p.branch) inServ[p.branch] = (inServ[p.branch] || 0) + 1; });

    const days = Math.max(1, daysBetween(dFrom, dTo) + 1);
    const months = Math.max(1, (daysBetween(fyFrom, t) + 1) / 30.44);
    const dB = {}, fB = {};
    let dT = 0, fT = 0;
    ses.forEach(s => {
      const d = d10(s.start_date), b = s.branch || "Unknown";
      if (d >= fyFrom) { fB[b] = (fB[b] || 0) + 1; fT++; }
      if (d >= dFrom && d <= dTo) { dB[b] = (dB[b] || 0) + 1; dT++; }
    });
    const bars = (obj, fmt) => {
      const e = Object.entries(obj).sort((a, b) => b[1] - a[1]);
      const max = e.length ? e[0][1] : 1;
      return e.length ? e.map(([b, n]) => `<div class="c3-bar"><span class="c3-bar-l">${esc(b)}</span><span class="c3-bar-t"><i style="width:${Math.max(4, n / max * 100)}%"></i></span><b>${fmt(n)}</b></div>`).join("") : `<div class="c3-empty-sm">No data in this period.</div>`;
    };

    set("d-total", patients.length.toLocaleString("en-IN"));
    set("d-active", active.toLocaleString("en-IN"));
    set("d-irregular", irregular.toLocaleString("en-IN"));
    set("d-inactive", inactive.toLocaleString("en-IN"));
    set("d-completed", completed.toLocaleString("en-IN"));
    set("d-avg", bNames.length ? Math.round(patients.length / bNames.length).toLocaleString("en-IN") : "0");
    set("d-top", esc(top));
    set("d-daily", (dT / days).toFixed(1));
    set("d-daily-sub", `${fdate(dFrom)} → ${fdate(dTo)} (${days}d)`);
    set("d-monthly", Math.round(fT / months).toLocaleString("en-IN"));
    set("d-inserv", bars(inServ, n => n));
    set("d-dailyb", bars(dB, n => (n / days).toFixed(1) + "/d"));
    set("d-monthlyb", bars(fB, n => Math.round(n / months) + "/mo"));
    $("#c3DashUpdated").textContent = "Updated " + new Date().toLocaleTimeString("en-IN", { hour: "2-digit", minute: "2-digit" });
  } catch (e) {
    void 0;
    $("#c3DashUpdated").textContent = "Dashboard failed — " + e.message;
  }
}

