        <div class="c3-up tone-${m.overdueFu.length ? "warn" : "ok"}"><span>📞</span><div><small>Next followup</small><b>${m.nextFu ? fdate(m.nextFu.next_followup_date) : m.overdueFu.length ? `${m.overdueFu.length} overdue` : "None scheduled"}</b><em>${m.nextFu ? esc(m.nextFu.followup_type || "") : ""}</em></div></div>
        <div class="c3-up tone-${m.due.overdue ? "neg" : m.due.next ? "warn" : "ok"}"><span>💰</span><div><small>Next due date</small><b>${m.due.overdue ? "Overdue now" : m.due.next ? fdate(m.due.next) : "—"}</b><em>${m.due.overdue ? money(m.due.overdueAmt) : m.due.next ? money(m.due.nextAmt) : "No pending dues"}</em></div></div>
