        <ol class="c3-journey">${m.branchList.map(x => `<li class="${x.branch === m.home ? "is-home" : ""}"><div><b>${esc(x.branch)}</b>${x.branch === m.home ? `<span class="c3-pill tone-ok">Home</span>` : ""}
