tOverview.after = body => {
  wireSections(body);
  body.addEventListener("click", e => { const o = e.target.closest("[data-open-client]"); if (o) openModal(o.dataset.openClient); });
};

async function loadReferrals(b) {
  const r = { by: b.m.ref.by, fields: b.m.ref.fields, brought: [] };
  for (const f of r.fields.slice(0, 3)) {
    const rows = await safe(list("Patient", [[f, "in", [b.pid, b.patient.patient_name].filter(Boolean)]], ["name", "patient_name", "sex", "creation"], 100), []);
    rows.forEach(x => { if (x.name !== b.pid && !r.brought.find(y => y.name === x.name)) r.brought.push(x); });
  }
  b.lazy.referrals = r;
  return r;
}

/* ---------------- BILLING ---------------- */
async function tBilling(b) {
  const m = b.m;
  const pays = b.lazy.payments || await loadPayments(b);
  const invs = b.invoices;
  const overdue = invs.filter(i => invClass(i) === "overdue");
  const modes = {};
  pays.forEach(x => { const k = x.mode_of_payment || "Other"; modes[k] = (modes[k] || 0) + peAmount(x); });
  const maxMode = Math.max(1, ...Object.values(modes));
  return sections("billing", [
    { id: "summary", icon: "💰", title: "Dues summary", tone: m.due.overdue ? "neg" : m.due.pending ? "warn" : "ok", badge: money(m.due.pending), wide: true,
      html: `<div class="c3-grid c3-g5">
        <div class="c3-money-hero tone-${m.due.overdue ? "neg" : m.due.pending ? "warn" : "ok"}"><small>Due amount</small><b>${money(m.due.pending)}</b><span>${m.due.withDues ? plural(m.due.withDues, "invoice") + " with balance" : "All settled"}</span></div>
        ${kv("Overdue amount", `<span class="${m.due.overdue ? "tone-neg" : "tone-ok"}">${money(m.due.overdueAmt)}</span>`)}
        ${kv("Next due date", m.due.next ? `${fdate(m.due.next)} — ${money(m.due.nextAmt)}` : "—")}
        ${kv("Total billed", money(m.billed))}
        ${kv("Paid", `<span class="tone-ok">${money(m.paid)}</span>`)}
      </div>` },
    overdue.length ? { id: "overdue", icon: "⏰", title: "Overdue invoices", tone: "neg", badge: overdue.length, wide: true,
      html: `<div class="c3-inv-grid-list">${overdue.map(invoiceCard).join("")}</div>` } : null,
    { id: "invoices", icon: "🧾", title: "All invoices", badge: invs.length, wide: true,
      html: `<div class="c3-filters" data-inv-filters>${["all", "unpaid", "partial", "overdue", "paid"].map((f, i) => `<button type="button" class="c3-fbtn${i ? "" : " is-on"}" data-f="${f}">${f === "all" ? "All" : INV_STATE[f][1]} (${f === "all" ? invs.length : invs.filter(x => invClass(x) === f).length})</button>`).join("")}</div>
        <div class="c3-inv-grid-list" data-inv-list>${invs.map(i => `<div data-cls="${invClass(i)}">${invoiceCard(i)}</div>`).join("") || `<div class="c3-empty-sm">No invoices.</div>`}</div>` },
    { id: "payments", icon: "💳", title: "Payments received", badge: pays.length, wide: true,
      html: pays.length ? `<div class="c3-bars">${Object.entries(modes).sort((a, c) => c[1] - a[1]).map(([k, v]) => `<div class="c3-bar"><span class="c3-bar-l">${esc(k)}</span><span class="c3-bar-t"><i style="width:${v / maxMode * 100}%"></i></span><b>${money(v)}</b></div>`).join("")}</div>
        <div class="c3-table-wrap"><table class="c3-mini-table"><thead><tr><th>Date</th><th>Receipt</th><th>Mode</th><th>Branch</th><th class="t-r">Amount</th></tr></thead><tbody>
        ${pays.map(x => `<tr><td>${fdate(x.posting_date)}</td><td>${esc(x.name)}</td><td>${esc(x.mode_of_payment || "—")}</td><td>${esc(x.branch || "—")}</td><td class="t-r tone-ok">${money(peAmount(x))}</td></tr>`).join("")}</tbody></table></div>`
        : `<div class="c3-empty-sm">No payment entries linked to this client's customer record.</div>` }
  ]);
}
tBilling.after = body => {
  wireSections(body);
  body.addEventListener("click", e => {
    const bill = e.target.closest("[data-bill]");
    if (bill) { openBill(bill.dataset.bill); return; }
    const f = e.target.closest("[data-inv-filters] .c3-fbtn");
    if (!f) return;
    $$("[data-inv-filters] .c3-fbtn", body).forEach(x => x.classList.toggle("is-on", x === f));
    $$("[data-inv-list] > [data-cls]", body).forEach(x => { x.hidden = !(f.dataset.f === "all" || x.dataset.cls === f.dataset.f || (f.dataset.f === "unpaid" && x.dataset.cls === "overdue")); });
  });
};
async function loadPayments(b) {
  const p = b.patient, f = ["name", "posting_date", "mode_of_payment", "party", "party_name", "branch", "base_received_amount", "received_amount", "paid_amount", "reference_no", "docstatus"];
  let rows = [];
  if (p.customer) rows = await safe(list("Payment Entry", [["party", "=", p.customer], ["docstatus", "=", 1], ["payment_type", "=", "Receive"]], f, 2000, "posting_date desc"), []);
  if (!rows.length && p.patient_name) rows = await safe(list("Payment Entry", [["party_name", "=", p.patient_name], ["docstatus", "=", 1], ["payment_type", "=", "Receive"]], f, 2000, "posting_date desc"), []);
  b.lazy.payments = rows.filter(x => !isExcluded(x.branch));
  return b.lazy.payments;
}

/* ---------------- PLANS ---------------- */
async function tPlans(b) {
  const pv = b.planView;
  if (!pv.length) return emptyHtml("📋", "No therapy plans", "Plans created for this client will appear here.");
  const cnt = s => pv.filter(x => x.h.state === s).length;
  return `<div class="c3-kpis">
      ${kpi("📋", "Plans", pv.length)}${kpi("▲", "On track", cnt("ok"), "ok")}${kpi("▼", "Behind pace", cnt("behind"), cnt("behind") ? "warn" : "")}
      ${kpi("⛔", "Past end date", cnt("overdue"), cnt("overdue") ? "neg" : "")}${kpi("🏁", "Completed", cnt("done"), "info")}${kpi("📦", "Completion", b.m.completion + "%")}
    </div>
    <div class="c3-cards c3-plan-rows">${pv.map(x => {
      const p = x.plan, h = x.h, st = PLAN_STATE[h.state] || PLAN_STATE.unknown;
      return `<article class="c3-card c3-accent tone-${st.c}">
        <header class="c3-card-h"><div><b>${esc(p.name)}</b><small>${esc(p.category || p.custom_health_status || "Therapy plan")}</small></div>${planStateChip(h)}</header>
        <div class="c3-grid c3-g4">
          ${kv("Branch", esc(p.branch || "—"))}${kv("Start", fdate(p.start_date))}
          ${kv("End date", `<span class="${h.state === "overdue" ? "tone-neg" : ""}">${fdate(h.due)}${h.estimated ? " (est.)" : ""}</span>`)}
          ${kv("Consultant", esc(p.custom_employee_name || p.consultant_name || b.users[p.owner] || "—"))}
          ${kv("Sessions", `${h.done} / ${h.total}`)}${kv("Balance", `<span class="${h.balance ? "tone-warn" : "tone-ok"}">${h.balance}</span>`)}
          ${kv("Expected by today", h.expected ? Math.round(h.expected) : "—")}${kv("Progress", h.pct + "%")}
        </div>
        ${bar(h.pct, st.c)}
        ${x.rows.length ? `<div class="c3-therapies">${x.rows.map(r => { const pc = r.total ? Math.round(r.done / r.total * 100) : 0; return `<div class="c3-th"><b>${esc(r.therapy)}</b><span>${r.done}/${r.total}</span><span class="${r.balance ? "tone-warn" : "tone-ok"}">${r.balance} left</span>${bar(pc, pc >= 100 ? "info" : "ok")}</div>`; }).join("")}</div>` : ""}
      </article>`;
    }).join("")}</div>`;
}
const kpi = (ic, label, v, tone) => `<div class="c3-kpi"><span class="c3-kpi-ic">${ic}</span><div><small>${label}</small><b class="${tone ? "tone-" + tone : ""}">${v}</b></div></div>`;

/* ---------------- SESSIONS ---------------- */
async function tSessions(b) {
  const s = b.sessions;
  if (!s.length) return emptyHtml("💆", "No therapy sessions", "Completed sessions will appear here.");
  const plans = [...new Set(s.map(x => x.therapy_plan).filter(Boolean))];
  const weights = s.filter(x => num(x.before_weight) > 0).sort((a, c) => String(a.start_date).localeCompare(String(c.start_date)));
  const wFirst = weights.length ? num(weights[0].before_weight) : 0;
  const wLast = weights.length ? (num(weights[weights.length - 1].after_weight) || num(weights[weights.length - 1].before_weight)) : 0;
  const wDiff = Math.round((wLast - wFirst) * 10) / 10;
  return `<div class="c3-kpis">
      ${kpi("💆", "Total", s.length)}${kpi("✅", "Submitted", s.filter(x => Number(x.docstatus) === 1).length, "ok")}${kpi("📝", "Draft", s.filter(x => Number(x.docstatus) === 0).length, "warn")}
      ${kpi("📆", "Avg / month", b.m.avgMonthly.toFixed(1), b.m.consistency === "Irregular" ? "warn" : "ok")}
      ${weights.length > 1 ? kpi("⚖️", "Weight change", (wDiff > 0 ? "+" : "") + wDiff + " kg", wDiff < 0 ? "ok" : wDiff > 0 ? "neg" : "") : kpi("🕒", "Last session", fdate(b.m.last))}
    </div>
    <div class="c3-filters"><label class="c3-select-l">📋 <select data-ses-plan><option value="">All plans</option>${plans.map(x => `<option>${esc(x)}</option>`).join("")}</select></label></div>
    <div class="c3-cards c3-c4" data-ses-grid></div>
    <div class="c3-more-wrap"><button type="button" class="c3-btn" data-ses-more>Show more sessions</button></div>`;
}
tSessions.after = (body, b) => {
  let shown = 16, plan = "";
  const grid = $("[data-ses-grid]", body), more = $("[data-ses-more]", body);
  const draw = () => {
    const rows = b.sessions.filter(x => !plan || x.therapy_plan === plan);
    grid.innerHTML = rows.slice(0, shown).map(x => {
      const ds = Number(x.docstatus), st = ds === 1 ? ["ok", "✅ Submitted"] : ds === 2 ? ["neg", "✕ Cancelled"] : ["warn", "📝 Draft"];
      const wl = num(x.weight_loss);
      return `<article class="c3-card c3-ses">
        <header class="c3-card-h"><div><b>${esc(x.name)}</b><small>📅 ${fdate(x.start_date)} ${x.start_time ? "🕐 " + ftime(x.start_time) : ""}</small></div><span class="c3-pill tone-${st[0]}">${st[1]}</span></header>
        <div class="c3-field f-green"><small>💆 Therapy</small><b>${esc(x.therapy_type || "—")}</b></div>
        <div class="c3-field f-blue"><small>📋 Plan</small><b>${esc(x.therapy_plan || "—")}</b></div>
        <div class="c3-field f-amber"><small>👩‍⚕️ Attended by</small><b>${esc(x.custom_practitioner_name || x.practitioner || "—")}</b></div>
        <div class="c3-grid c3-g2"><div class="c3-field f-purple"><small>⏱ Duration</small><b>${esc(x.duration || "—")} min</b></div><div class="c3-field f-teal"><small>🏢 Branch</small><b>${esc(x.branch || "—")}</b></div></div>
        ${x.before_weight || x.after_weight ? `<div class="c3-field f-rose"><small>⚖️ Weight</small><b>${esc(x.before_weight || "—")} → ${esc(x.after_weight || "—")} ${wl ? `<span class="${wl > 0 ? "tone-ok" : "tone-neg"}">(${wl > 0 ? "−" : "+"}${Math.abs(wl)})</span>` : ""}</b></div>` : ""}
      </article>`;
    }).join("");
    more.hidden = rows.length <= shown;
  };
  $("[data-ses-plan]", body).addEventListener("change", e => { plan = e.target.value; shown = 16; draw(); });
  more.addEventListener("click", () => { shown += 16; draw(); });
  draw();
};

/* ---------------- APPOINTMENTS ---------------- */
async function tAppointments(b) {
  const slotSeconds = v => { const parts = String(v || "0:0:0").split(":").map(num); return parts[0] * 3600 + (parts[1] || 0) * 60 + (parts[2] || 0); };
  const a = b.appts.slice().sort((x, y) => d10(y.appointment_date).localeCompare(d10(x.appointment_date)) || slotSeconds(y.appointment_time) - slotSeconds(x.appointment_time));
  if (!a.length) return emptyHtml("📅", "No appointments", "Book the next visit from the Book appointment button.");
  const statuses = ["All", ...new Set(a.map(x => x.status || "Unknown"))];
  const up = a.filter(x => d10(x.appointment_date) >= b.m.t && !["cancelled", "no show"].includes(lc(x.status))).length;
  const noShow = a.filter(x => lc(x.status) === "no show").length;
  return `<div class="c3-kpis">${kpi("📅", "Total", a.length)}${kpi("⏭️", "Upcoming", up, up ? "ok" : "")}${kpi("✅", "Closed / checked out", a.filter(x => ["closed", "checked out"].includes(lc(x.status))).length, "ok")}
      ${kpi("🙈", "No show", noShow, noShow ? "neg" : "")}${kpi("✕", "Cancelled", a.filter(x => lc(x.status) === "cancelled").length, "warn")}</div>
    <div class="c3-filters" data-appt-f>${statuses.map((s, i) => `<button type="button" class="c3-fbtn${i ? "" : " is-on"}" data-f="${esc(s)}">${esc(s)} (${s === "All" ? a.length : a.filter(x => (x.status || "Unknown") === s).length})</button>`).join("")}</div>
    <div class="c3-cards c3-c4" data-appt-grid></div>
    <div class="c3-pager-sm" data-appt-pager></div>`;
}
tAppointments.after = (body, b) => {
  let f = "All", page = 1;
  const PS = 16, t = b.m.t;
  const slotSeconds = v => { const p = String(v || "0:0:0").split(":").map(num); return p[0] * 3600 + (p[1] || 0) * 60 + (p[2] || 0); };
  const sortedAppts = b.appts.slice().sort((x,y) => d10(y.appointment_date).localeCompare(d10(x.appointment_date)) || slotSeconds(y.appointment_time)-slotSeconds(x.appointment_time));
  const draw = () => {
    const rows = sortedAppts.filter(x => f === "All" || (x.status || "Unknown") === f);
    const pages = Math.max(1, Math.ceil(rows.length / PS));
    page = Math.min(page, pages);
    $("[data-appt-grid]", body).innerHTML = rows.slice((page - 1) * PS, page * PS).map(x => {
      const s = lc(x.status), d = d10(x.appointment_date);
      const tone = ["closed", "checked out"].includes(s) ? "ok" : s === "cancelled" ? "warn" : s === "no show" ? "neg" : d >= t ? "info" : "mute";
      return `<article class="c3-card c3-accent tone-${tone}">
        <header class="c3-card-h"><div><b>${d === t ? "📍 Today" : d > t ? "⏭️ " + fdate(d) : fdate(d)}</b><small>🕐 ${ftime(x.appointment_time) || "—"}</small></div><span class="c3-pill tone-${tone}">${esc(x.status || "—")}</span></header>
        <div class="c3-field f-green"><small>📌 Type</small><b>${esc(x.appointment_type || "General")}</b></div>
        <div class="c3-field f-blue"><small>💆 Therapy</small><b>${esc(x.therapy_type1 || x.therapy_type || "—")}</b></div>
        <div class="c3-field"><small>🩺 Concern</small><b>${esc(x.concern || "—")}</b></div>
        <div class="c3-grid c3-g2">
          <div class="c3-field f-amber"><small>👩‍⚕️ Practitioner</small><b>${esc(x.practitioner_name || x.practitioner || "—")}</b></div>
          <div class="c3-field f-teal"><small>🏢 Branch</small><b>${esc(x.branch || "—")}</b></div>
        </div>
        ${x.call_back_status ? `<div class="c3-mini tone-warn">📞 Confirmation: ${esc(x.call_back_status)}</div>` : ""}
        ${x.service_room || x.service_unit ? `<div class="c3-mini">🚪 ${esc([x.service_room, x.service_unit].filter(Boolean).join(" / "))}</div>` : ""}
      </article>`;
    }).join("");
    $("[data-appt-pager]", body).innerHTML = pages > 1 ? `<button type="button" class="c3-btn c3-btn-sm" data-p="-1" ${page === 1 ? "disabled" : ""}>Previous</button><span>Page ${page} of ${pages}</span><button type="button" class="c3-btn c3-btn-sm" data-p="1" ${page === pages ? "disabled" : ""}>Next</button>` : "";
  };
  body.addEventListener("click", e => {
    const fb = e.target.closest("[data-appt-f] .c3-fbtn");
    if (fb) { f = fb.dataset.f; page = 1; $$("[data-appt-f] .c3-fbtn", body).forEach(x => x.classList.toggle("is-on", x === fb)); draw(); return; }
    const pb = e.target.closest("[data-appt-pager] [data-p]");
    if (pb) { page += Number(pb.dataset.p); draw(); }
  });
  draw();
};

/* ---------------- FOLLOWUPS ---------------- */
function fuType(t) {
  const s = lc(t);
  if (s.includes("appointment")) return ["blue", "📅"];
  if (s.includes("diet")) return ["green", "🥗"];
  if (/pending|due|balance|payment/.test(s)) return ["orange", "₹"];
  if (s.includes("feedback")) return ["amber", "⭐"];
  if (s.includes("unjoined")) return ["red", "👤"];
  if (s.includes("existing")) return ["teal", "📞"];
  if (/treatment|therapy/.test(s)) return ["purple", "🩺"];
  if (s.includes("maintenance")) return ["slate", "🔄"];
  if (/complaint|concern/.test(s)) return ["red", "🗣️"];
  return ["slate", "📌"];
}
function followupCards(rows, t) {
  return rows.map(r => {
    const [col, ic] = fuType(r.followup_type);
    const st = lc(r.status), done = ["completed", "closed", "done"].includes(st);
    const next = d10(r.next_followup_date);
    const late = next && next < t && !done && st !== "cancelled";
    return `<article class="c3-card c3-fu f-${col}${late ? " is-late" : ""}" data-type="${esc(r.followup_type || "Other")}">
      <header class="c3-card-h"><div><span class="c3-pill c3-fu-type">${ic} ${esc(r.followup_type || "Followup")}</span><small>📅 ${fdate(r.followup_date || r.creation)} ${r.followup_time ? ftime(r.followup_time) : ""}</small></div>
        <span class="c3-pill tone-${done ? "ok" : st.includes("not reachable") ? "neg" : "warn"}">${esc(r.status || "Open")}</span></header>
      <p class="c3-fu-remark">${esc(r.remarks || r.client_response || "No remarks recorded.")}</p>
      ${r.client_response && r.remarks ? `<p class="c3-fu-resp">💬 Client said: ${esc(r.client_response)}</p>` : ""}
      <div class="c3-grid c3-g3">
        ${kv("By", esc(r.employee_name || r.employee || r.followup_by || "—"))}
        ${kv("Channel", esc(r.contact_channel || "—"))}
        ${kv("Outcome", esc(r.call_outcome || "—"))}
        ${kv("Priority", esc(r.priority || "Normal"), lc(r.priority) === "high" ? "is-neg" : "")}
        ${kv("Branch", esc(r.branch || "—"))}
        ${kv("Next followup", next ? `<span class="${late ? "tone-neg" : ""}">${fdate(next)}${late ? " ⏰ due" : ""}</span>` : "—")}
      </div>
      ${r.linked_invoice || r.linked_appointment || r.linked_therapy_plan ? `<div class="c3-mini">🔗 ${esc([r.linked_invoice, r.linked_appointment, r.linked_therapy_plan].filter(Boolean).join(", "))}</div>` : ""}
    </article>`;
  }).join("");
}
async function tFollowups(b) {
  const rows = b.followups;
  if (!rows.length) return emptyHtml("📞", "No followups", "Followups logged for this client will show here with full call history.");
  const t = b.m.t;
  const types = {};
