    const [vitals, enc] = await Promise.all([
      safe(list("Vital Signs", [["patient", "=", b.pid], ["docstatus", "!=", 2]], ["name", "signs_date", "height", "weight", "bmi", "bp", "pulse", "temperature", "nutrition_note"], 100, "signs_date desc"), []),
      safe(list("Patient Encounter", [["patient", "=", b.pid], ["docstatus", "!=", 2]], ["name", "encounter_date", "practitioner_name", "medical_department", "encounter_comment"], 100, "encounter_date desc"), [])
    ]);
    b.lazy.medical = { vitals, enc };
  }
  const { vitals, enc } = b.lazy.medical;
  const w = b.sessions.filter(x => num(x.before_weight) > 0).sort((a, c) => String(a.start_date).localeCompare(String(c.start_date)));
  const wStart = w.length ? num(w[0].before_weight) : 0;
  const wNow = w.length ? (num(w[w.length - 1].after_weight) || num(w[w.length - 1].before_weight)) : 0;
  const wd = Math.round((wNow - wStart) * 10) / 10;
  const byPlan = b.plans.map(p => ({ n: p.name, s: p.custom_health_status || "—", br: p.branch }));
  const pts = w.slice(-24);
