  if (pts.length > 1) {
    const vals = pts.map(x => num(x.after_weight) || num(x.before_weight));
    const mn = Math.min(...vals), mx = Math.max(...vals), rg = Math.max(0.1, mx - mn);
    const path = vals.map((v, i) => `${(i / (vals.length - 1) * 300).toFixed(1)},${(52 - (v - mn) / rg * 44).toFixed(1)}`).join(" ");
    spark = `<svg class="c3-spark" viewBox="0 0 300 56" preserveAspectRatio="none" role="img" aria-label="Weight trend"><polyline points="${path}" /></svg>`;
  }
  return sections("medical", [
    { id: "flag", icon: med.isMedical ? "🩺" : "🌿", title: med.isMedical ? "Medical client" : "Non-medical client", tone: med.flagged.length ? "neg" : med.isMedical ? "warn" : "ok", badge: med.flagged.length ? med.flagged.length + " major" : "", wide: true,
      html: med.flagged.length ? `<div class="c3-alerts">${med.flagged.map(i => `<div class="c3-alert tone-neg"><span>⚠️</span><p><b>${esc(i.label)}:</b> ${esc(i.text)}</p></div>`).join("")}</div>`
        : `<div class="c3-alert tone-${med.isMedical ? "warn" : "ok"}"><span>${med.isMedical ? "🩺" : "🌿"}</span><p>${med.isMedical ? "Marked medical on a therapy plan. Check history before every procedure." : "No major medical conditions recorded."}</p></div>` },
    { id: "history", icon: "📋", title: "Recorded medical details", badge: med.issues.length,
      html: med.issues.length ? `<div class="c3-grid c3-g2">${med.issues.map(i => kv(esc(i.label), esc(i.text), med.flagged.includes(i) ? "is-neg" : "")).join("")}</div>` : `<div class="c3-empty-sm">No allergies, medication or history filled on the Patient record.</div>` },
    { id: "weight", icon: "⚖️", title: "Weight journey", badge: w.length ? (wd > 0 ? "+" : "") + wd + " kg" : "", tone: wd < 0 ? "ok" : wd > 0 ? "neg" : "mute",
      html: w.length ? `<div class="c3-grid c3-g3">${kv("Starting weight", wStart + " kg")}${kv("Latest weight", wNow + " kg")}${kv("Change", `<span class="${wd < 0 ? "tone-ok" : wd > 0 ? "tone-neg" : ""}">${wd < 0 ? "▼" : wd > 0 ? "▲" : "="} ${Math.abs(wd)} kg</span>`)}</div>${spark}` : `<div class="c3-empty-sm">No weights captured in sessions.</div>` },
    { id: "plans", icon: "🏷️", title: "Health status by plan", badge: byPlan.length,
      html: byPlan.length ? `<div class="c3-chips">${byPlan.map(x => `<span class="c3-chip ${lc(x.s) === "medical" ? "tone-neg" : ""}">${lc(x.s) === "medical" ? "🩺" : "🌿"} ${esc(x.n)}: ${esc(x.s)}</span>`).join("")}</div>` : `<div class="c3-empty-sm">No plans.</div>` },
    { id: "vitals", icon: "❤️", title: "Vital signs", badge: vitals.length,
      html: vitals.length ? `<div class="c3-table-wrap"><table class="c3-mini-table"><thead><tr><th>Date</th><th>Weight</th><th>BMI</th><th>BP</th><th>Pulse</th><th>Note</th></tr></thead><tbody>${vitals.map(v => `<tr><td>${fdate(v.signs_date)}</td><td>${esc(v.weight || "—")}</td><td>${esc(v.bmi || "—")}</td><td>${esc(v.bp || "—")}</td><td>${esc(v.pulse || "—")}</td><td>${esc(v.nutrition_note || "")}</td></tr>`).join("")}</tbody></table></div>` : `<div class="c3-empty-sm">No vital signs recorded.</div>` },
    { id: "encounters", icon: "👨‍⚕️", title: "Doctor consultations", badge: enc.length,
      html: enc.length ? `<div class="c3-cards c3-c2">${enc.map(e => `<article class="c3-card"><header class="c3-card-h"><div><b>${fdate(e.encounter_date)}</b><small>${esc(e.practitioner_name || "")} ${esc(e.medical_department || "")}</small></div></header>${e.encounter_comment ? `<p class="c3-fu-remark">${esc(stripHtml(e.encounter_comment))}</p>` : ""}</article>`).join("")}</div>` : `<div class="c3-empty-sm">No consultations recorded.</div>` }
  ]);
}
