tMessages.after = (body, b) => {
  let tpl = ($(".c3-tpl.is-on", body) || {}).dataset?.k || "thanks";
  const ta = $("[data-msg-text]", body);
  const vars = () => { const x = {}; $$("[data-var]", body).forEach(i => { if (i.value) x[i.dataset.var] = i.type === "date" ? fdate(i.value) : i.value; }); return x; };
  const draw = () => {
    const t = TEMPLATES.find(x => x.k === tpl);
    $("[data-msg-offer]", body).hidden = tpl !== "offer";
    ta.value = fillTpl(t.t, msgVars(b, vars()));
    warn();
  };
  const warn = () => { const miss = (ta.value.match(/\{\w+\}/g) || []); $("[data-msg-warn]", body).innerHTML = miss.length ? `<span class="tone-warn">⚠️ Fill before sending: ${esc([...new Set(miss)].join(", "))}</span>` : ""; };
  ta.addEventListener("input", warn);
  body.addEventListener("input", e => { if (e.target.matches("[data-var]")) draw(); });
  body.addEventListener("click", async e => {
    const tb = e.target.closest(".c3-tpl");
    if (tb) { tpl = tb.dataset.k; $$(".c3-tpl", body).forEach(x => x.classList.toggle("is-on", x === tb)); draw(); return; }
    const sb = e.target.closest("[data-send]");
