    if (sb.dataset.send === "copy") { try { await navigator.clipboard.writeText(text); toast("Message copied.", "ok"); } catch (err) { toast("Copy blocked by browser.", "warn"); } return; }
    const ph = b.m.phones[Number(($("[data-msg-to]", body) || {}).value || 0)];
    if (!ph) return;
    const url = sb.dataset.send === "wa" ? `https://wa.me/91${ph.number}?text=${encodeURIComponent(text)}` : `sms:+91${ph.number}?body=${encodeURIComponent(text)}`;
    window.open(url, "_blank", "noopener");
    const t = TEMPLATES.find(x => x.k === tpl);
    safe(addRemark(b, `[Message] ${sb.dataset.send === "wa" ? "WhatsApp" : "SMS"} sent to ${ph.label} ${maskMobile(ph.number)}: ${t.l}`).then(() => { b.lazy.remarks = null; }), null);
    toast(sb.dataset.send === "wa" ? "Opening WhatsApp…" : "Opening SMS app…", "ok");
  });
  draw();
};

/* ==========================================================================
   EVENTS
   ========================================================================== */
function wire() {
  const search = $("#c3Search");

  /* ------------------------------------------------------------------
     Do NOT stop propagation in the CAPTURE phase here.
     The previous code did `APP.addEventListener(ev, handler, true)`,
     which silently killed every listener attached to #c3Search (and
     every other control) before it could fire — the reason typing a
     name or a mobile number never produced the client dropdown.
     Bubble phase only.
     ------------------------------------------------------------------ */
  ["keydown", "keyup", "keypress", "input"].forEach(ev => APP.addEventListener(ev, e => {
    const t = e.target;
    if (t && t.matches && t.matches("input, textarea, select")) e.stopPropagation();
  }));

  /* ---- search box: live client lookup (mobile or name) ---- */
  search.addEventListener("input", () => {
    const val = search.value;
    $("#c3SearchClear").hidden = !val;
    clearTimeout(lookTimer);
    if (!val.trim()) { hideLookup(); applyFilters(); return; }
    const rule = lookupRule(val);
    if (!rule.ok) { hideLookup(); return; }
    lookTimer = setTimeout(() => runLookup(val), 200);
  });

  search.addEventListener("focus", () => {
    if (lookupRule(search.value).ok) runLookup(search.value);
  });

  search.addEventListener("keydown", e => {
    if (e.key === "Enter") { e.preventDefault(); applyFilters(); if (lookupRule(search.value).ok) runLookup(search.value); }
    if (e.key === "Escape") hideLookup();
  });

  $("#c3SearchClear").addEventListener("click", () => { search.value = ""; $("#c3SearchClear").hidden = true; hideLookup(); applyFilters(); search.focus(); });

  $("#c3Lookup").addEventListener("click", e => {
    const o = e.target.closest("[data-look-open]"), r = e.target.closest("[data-look-row]");
    if (o) openModal(lookRows[+o.dataset.lookOpen].name);
    if (r) showSingleInList(lookRows[+r.dataset.lookRow]);
  });

  document.addEventListener("click", e => { if (!e.target.closest(".c3-search")) hideLookup(); });

  $("#c3SearchBtn").addEventListener("click", () => { applyFilters(); if (lookupRule(search.value).ok) runLookup(search.value); });
  $("#c3Branch").addEventListener("change", applyFilters);
  $("#c3Status").addEventListener("change", applyFilters);
  $("#c3Mode").addEventListener("change", () => loadMain($("#c3From").value || null, $("#c3To").value || null));
  $("#c3UnpaidBtn").addEventListener("click", () => {
    S.unpaid = !S.unpaid;
    $("#c3UnpaidBtn").classList.toggle("is-on", S.unpaid);
    applyFilters();
  });
  $("#c3ClearBtn").addEventListener("click", () => {
    search.value = ""; $("#c3SearchClear").hidden = true; hideLookup();
    $("#c3Branch").value = ""; $("#c3Status").value = ""; $("#c3Mode").value = "";
    setQuick("today");
  });
  $("#c3Export").addEventListener("click", exportCsv);

  $$(".c3-q").forEach(b => b.addEventListener("click", () => setQuick(b.dataset.key)));
  const dateChange = () => { $$(".c3-q").forEach(x => x.classList.remove("is-on")); loadMain($("#c3From").value || null, $("#c3To").value || null); };
  $("#c3From").addEventListener("change", dateChange);
  $("#c3To").addEventListener("change", dateChange);

  $("#c3Body").addEventListener("click", e => {
    const d = e.target.closest("[data-drawer]");
    if (d) { e.stopPropagation(); openDrawer(d.dataset.drawer); return; }
    if (e.target.closest(".c3-phone")) return;
    const row = e.target.closest("[data-pid]");
    if (row) openModal(row.dataset.pid);
  });
  $("#c3Body").addEventListener("keydown", e => { const row = e.target.closest("[data-pid]"); if (row && e.key === "Enter" && e.target === row) openModal(row.dataset.pid); });
  $("#c3Prev").addEventListener("click", () => { S.page--; renderTable(); });
  $("#c3Next").addEventListener("click", () => { S.page++; renderTable(); });
  $("#c3PageNums").addEventListener("click", e => { const b = e.target.closest("[data-page]"); if (b) { S.page = +b.dataset.page; renderTable(); } });

  $("#c3DrawerClose").addEventListener("click", closeDrawer);
  $("#c3DrawerOverlay").addEventListener("click", closeDrawer);
  $("#c3DrawerList").addEventListener("click", e => { const b = e.target.closest("[data-bill]"); if (b) openBill(b.dataset.bill); });
  $$(".c3-df").forEach(b => b.addEventListener("click", () => { drawerFilter = b.dataset.f; $$(".c3-df").forEach(x => x.classList.toggle("is-on", x === b)); renderDrawer(); }));
  $("#c3DrawerOpen360").addEventListener("click", () => openModal(drawerPid));

  $("#c3ModalOverlay").addEventListener("click", closeModal);
  $("#c3Tabs").addEventListener("click", e => { const t = e.target.closest("[data-tab]"); if (t && M.b) loadTab(t.dataset.tab); });
  document.addEventListener("keydown", e => {
    if (e.key !== "Escape") return;
    if ($("#c3Modal").classList.contains("is-open")) closeModal();
    else if ($("#c3Drawer").classList.contains("is-open")) closeDrawer();
  });

  $("#c3DashToggle").addEventListener("click", () => {
    const d = $("#c3Dash"), col = d.classList.toggle("is-collapsed");
    $("#c3DashToggle").setAttribute("aria-expanded", !col);
    pref("dashCollapsed", col);
    if (!col) loadDash();
  });
  $("#c3DashRefresh").addEventListener("click", loadDash);
  $("#c3Dash").addEventListener("click", e => {
    const c = e.target.closest("[data-status-filter]");
    if (!c) return;
    $("#c3Status").value = c.dataset.statusFilter;
    applyFilters();
    $("#c3Filters").scrollIntoView({ behavior: "smooth", block: "start" });
  });
}
function setQuick(key) {
  $$(".c3-q").forEach(x => x.classList.toggle("is-on", x.dataset.key === key));
  const [f, t] = qRange(key);
  $("#c3From").value = f || "";
  $("#c3To").value = t || "";
  loadMain(f, t);
}

/* ==========================================================================
   INIT
   ========================================================================== */
wire();
if (pref("dashCollapsed")) { $("#c3Dash").classList.add("is-collapsed"); $("#c3DashToggle").setAttribute("aria-expanded", "false"); }
loadModes();
setQuick("today");

/* Debug hook for IT team: window.CLIENT360.open("PATIENT-ID") */
window.CLIENT360 = { open: openModal, reload: () => setQuick("today"), config: CFG, version: "8.1" };

})();
